import{_ as o,o as d,c,a2 as a}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"3.0.0-WP06g2 — L1 本地化 + 系统 IME","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/3.0.0-WP06g2.md","filePath":"zh/release/3.0.0-WP06g2.md"}'),t={name:"zh/release/3.0.0-WP06g2.md"};function n(r,e,s,i,l,_){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-0-0-wp06g2-—-l1-本地化-系统-ime" tabindex="-1">3.0.0-WP06g2 — L1 本地化 + 系统 IME <a class="header-anchor" href="#_3-0-0-wp06g2-—-l1-本地化-系统-ime" aria-label="Permalink to &quot;3.0.0-WP06g2 — L1 本地化 + 系统 IME&quot;">​</a></h1><p>l1_i18n 批次：Ring-3 世界变成双语的，中文输入成为一项 系统服务。</p><h2 id="变更内容" tabindex="-1">变更内容 <a class="header-anchor" href="#变更内容" aria-label="Permalink to &quot;变更内容&quot;">​</a></h2><ul><li><strong>i18n 框架。</strong> 274 个 Ring-3 程序中的每一个都携带 <code>i18n/en.json</code> + <code>i18n/zh.json</code>（文件夹应用在 <code>src/L1/&lt;name&gt;/i18n/</code>，遗留平铺程序在 <code>src/L1/_i18n/&lt;name&gt;/</code> 下）。资源编译成逐应用按键排序的 表（<code>gen_userprogs.py</code>，严格门禁——缺资源即构建失败）； <code>_shared/i18n.h</code> 提供 <code>tr_()</code> 运行时（每进程一次 <code>L1SVC DISP/LANG_GET</code> 探测，zh 缺失回退 en，en 缺失回退 键名）。L0 侧保留一张共享表 （<code>etc/i18n/l0/{en,zh}.json</code> → <code>tools/gen_l0_i18n.py</code>）。 没有硬编码：源码写 <code>tr_(&quot;key&quot;)</code>，资源文件携带文本。</li><li><strong><code>lang zh</code> 现在是真的了。</strong> 五条 <code>lang</code> 消息的历史 zh 列 自 v2.2.0 抢救以来一直是英文占位符——它们现在渲染真正的 中文。<code>help -a</code> 为全部 274 个程序显示中文注册表提示； shell 内建、文件工具（usage/error 句子）、<code>stat</code>、 <code>free</code>、<code>ps</code>、<code>date</code> 遵循 zh_CN 约定（句子翻译，列骨架 英文）。</li><li><strong>系统 IME。</strong> 一个引擎 + 一个会话住在 L0 显示服务里 （<code>ime_session.c</code>）；编辑器经新的 <code>L1SVC_DISP_IME_BEGIN/KEY/END</code> 操作（13/14/15，按编号 契约追加）驱动它，绝不内嵌副本。候选词组优先 （622 个手工编写的高频词，池化表），然后是单字（全部 3755 个一级汉字），再一个智能组词候选（前 2-3 段的 精确音节切分）。每页九个；PageUp/PageDown（或 <code>-</code>/<code>=</code>） 翻页；数字 1-9 选择；空格选第一个；Enter 提交原始字母； Esc 清除。<code>ime -i</code>（交互式控制台组词行）运行同一个 引擎。</li><li><strong>编辑器。</strong> <code>editor_core.h</code> 具备 UTF-8 字形感知（按字符 移动、整字形删除并精确擦除单元格、多字节 插入），新增 <code>^K</code> 剪切 / <code>^R</code> 复制 / <code>^U</code> 粘贴，F2 切换 系统 IME（组词条渲染在状态行上）。 <code>vi</code> 真正模态化：同一引擎之上的 CMD 模式（<code>hjkl</code>、<code>x</code>、 <code>dd</code>、<code>yy</code>、<code>p</code>、<code>i/a/o</code>、<code>:w/:q/:wq/:q!</code>）。</li><li><strong>make-all 缺口关闭。</strong> <code>userprogs_data.h</code> 成为真正的 make 目标（见 KNOWN_ISSUES）；i18n json 文件也进入过期 集合。</li></ul><h2 id="途中活捉" tabindex="-1">途中活捉 <a class="header-anchor" href="#途中活捉" aria-label="Permalink to &quot;途中活捉&quot;">​</a></h2><p>词组池没有 NUL 分隔符（生成器数了 +1 却从不追加——整个 词库静默地永远匹配不上）；词组二分查找在长度平局时方向 搞反；智能组词排在真实字符之上；<code>l1_l1_dispatch</code> 渲染从不 NUL 终止（每次 <code>help -a</code> 的 strlen 都越界跑进堆约 100 字节）；ush 自己的帮助缓冲停在 8 KiB；串口 CSI 表缺少 xterm F 键序列（F2 从真实终端无法到达——原始 0x90..0x9B 不会从串口到达）。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>i18n 测试组 7/7、IME 测试组 3/3、编辑器测试组 10/10、逐程序 提示测试组 4/4（全部 274 条中文提示逐字节扫描）、WP06g1 回归集（chinesetest 81/81、V4/V4b/V5、字体审计 6763+682） 在最终镜像上全绿。</p>',8)])])}const p=o(t,[["render",n]]);export{g as __pageData,p as default};
